formulas.expression:
AND(
    /* Monday = 1 … Friday = 5 */
    WEEKDAY(DATEVALUE({!$Flow.CurrentDateTime})) >= 2,
    WEEKDAY(DATEVALUE({!$Flow.CurrentDateTime})) <= 6,

    /* Time between 09:30 and 18:00 */
    TEXT(TIMEVALUE({!$Flow.CurrentDateTime})) >= "08:30:00",
    TEXT(TIMEVALUE({!$Flow.CurrentDateTime})) <= "17:00:00"
)
